# Writes the hedra command files of the penguin slide's world (every model but the hero):
# floe3/5/8.txt (ice floes of the run), seal.txt, fish.txt, puff.txt, splash.txt, chunk.txt,
# berg.txt, ridge.txt, water.txt. Run from models/env: /usr/bin/python3 make_env.py.
# hedra: up Z, front -Y (the GLB comes out Y up, front +Z: towards the game's camera).
# Colours are exact Mist GB (sRGB 0..1), so the bake snaps them with no error.
import math, random

C = {"dark": (0.176, 0.106, 0.000), "teal": (0.118, 0.376, 0.431),
     "mint": (0.353, 0.725, 0.659), "pale": (0.769, 0.941, 0.761)}


def mat(name, colour):
    r, g, b = C[colour]
    return f"material new {name} --base-color {r:.3f} {g:.3f} {b:.3f} --no-slot"


def write(name, lines):
    with open(f"{name}.txt", "w") as f:
        f.write("\n".join(lines).strip() + "\n")


# ---------------------------------------------------------------- ice floes
# A floe of the run: an ice body L x 1.4 m whose front shows 0.24 m above the sea (it reaches 0.36 m
# down, under the water at -0.3), its ends and front slanting in towards the bottom (the gap between
# two floes reads as a V of broken ice), and a snow cap 0.08 m thick overhanging the front by 0.04 m.
# A few low drifts on the back half of the cap (behind the penguin's lane at y 0). Faces nobody sees
# (the body's top under the cap, its back and bottom, the cap's underside) are deleted.
def floe(L, seed):
    rnd = random.Random(seed)
    out = [f"# Ice floe, {L} m long: ice body, snow cap, drifts. Generated by make_env.py.",
           "new", mat("Ice", "mint"), mat("Snow", "pale"),
           "add mesh cube --name Body --size 1 --location 0 0 -0.24",
           f"scale {L} 1.4 0.36", "apply --scale", "material assign Ice",
           "active Body", "mode edit",
           'select face where "normal.z < -0.9"',
           f"scale {(L - 0.4) / L:.4f} 0.85 1",
           "select all", "subdivide --cuts 2",
           'select vert where "pos.z < -0.1"',
           f"randomize --amount 0.04 --seed {seed}",
           'select face where "normal.z < -0.9 || normal.z > 0.9 || normal.y > 0.9"', "delete only-faces",
           "mode object",
           "add mesh cube --name Cap --size 1 --location 0 -0.02 -0.04",
           f"scale {L + 0.06:.2f} 1.48 0.08", "apply --scale", "material assign Snow",
           "active Cap", "mode edit", 'select face where "normal.z < -0.9 || normal.y > 0.9"', "delete only-faces", "mode object"]
    n = max(1, int(L / 2.2))
    for i in range(n):
        x = -L / 2 + (i + 0.5 + rnd.uniform(-0.25, 0.25)) * L / n
        w = rnd.uniform(0.4, 0.7)
        out += [f"add mesh uv-sphere --name Drift{i} --segments 6 --rings 3 --radius 0.5 --location {x:.2f} 0.56 0",
                f"scale {w:.2f} 0.26 0.12", "apply --scale", "material assign Snow",
                f"active Drift{i}", "mode edit", 'select face where "pos.z < -0.01"', "delete only-faces", "mode object"]
    out += ["select all", "active Cap", "join", "rename Cap Floe", "shade flat", f"export floe{L}.glb"]
    write(f"floe{L}", out)


for L, s in ((3, 3), (5, 5), (8, 8)):
    floe(L, s)

# ---------------------------------------------------------------- seal
# A seal lying on the ice, 1.0 m long, its head raised towards the front (-Y): it faces the oncoming
# penguin (baked yaw -90: front to -X). Teal body (seal ramp step 1), a mint muzzle, dark nose.
write("seal", [
    "# Seal lying on the ice, head up and forward (-Y). Generated by make_env.py.",
    "new", mat("Seal", "teal"), mat("Muzzle", "mint"), mat("Nose", "dark"),
    "add mesh uv-sphere --name Body --segments 8 --rings 5 --radius 0.5 --location 0 0.08 0.17",
    "scale 0.46 1.0 0.34", "apply --scale", "material assign Seal",
    "add mesh uv-sphere --name Head --segments 8 --rings 5 --radius 0.5 --location 0 -0.42 0.38",
    "scale 0.3 0.32 0.28", "apply --scale", "material assign Seal",
    "add mesh uv-sphere --name Snout --segments 6 --rings 3 --radius 0.5 --location 0 -0.58 0.34",
    "scale 0.17 0.14 0.12", "apply --scale", "material assign Muzzle",
    "add mesh cube --name Nosetip --size 1 --location 0 -0.66 0.37",
    "scale 0.08 0.05 0.06", "apply --scale", "material assign Nose",
    "add mesh cone --name Tail --vertices 4 --radius1 0.16 --radius2 0 --depth 0.3 --location 0 0.66 0.1 --rotation -90 0 45",
    "apply --rotation", "scale 1.6 1 0.5", "apply --scale", "material assign Seal",
    "add mesh cube --name FlipL --size 1 --location -0.25 -0.15 0.05",
    "scale 0.16 0.24 0.06", "apply --scale", "material assign Seal",
    "add mesh cube --name FlipR --size 1 --location 0.25 -0.15 0.05",
    "scale 0.16 0.24 0.06", "apply --scale", "material assign Seal",
    "select all", "active Body", "join", "rename Body Seal", "shade flat", "export seal.glb"])

# ---------------------------------------------------------------- fish (pickup)
# A fish 0.42 m long, nose to -Y, a diamond body and a forked tail; pale (glint ramp), drawn unlit
# so it glints the same from every side while it turns.
write("fish", [
    "# Fish pickup, 0.42 m, nose -Y. Generated by make_env.py.",
    "new", mat("Fish", "pale"), mat("Fin", "mint"),
    "add mesh uv-sphere --name Body --segments 6 --rings 4 --radius 0.5 --location 0 -0.04 0",
    "scale 0.1 0.3 0.17", "apply --scale", "material assign Fish",
    "add mesh cone --name Tail --vertices 4 --radius1 0.11 --radius2 0 --depth 0.14 --location 0 0.15 0 --rotation 90 45 0",
    "apply --rotation", "scale 0.5 1 1.1", "apply --scale", "material assign Fin",
    "select all", "active Body", "join", "rename Body Fish", "shade flat", "export fish.glb"])

# ---------------------------------------------------------------- snow puff
# Three lumps of snow (0.34 m across): the spray behind the sliding penguin and the landing puff.
write("puff", [
    "# Snow puff, three lumps. Generated by make_env.py.",
    "new", mat("Snow", "pale"),
    "add mesh ico-sphere --name A --subdivisions 1 --radius 0.12 --location 0 0 0.12", "material assign Snow",
    "add mesh ico-sphere --name B --subdivisions 1 --radius 0.09 --location 0.12 0.04 0.08", "material assign Snow",
    "add mesh ico-sphere --name C --subdivisions 1 --radius 0.08 --location -0.1 -0.05 0.07", "material assign Snow",
    "select all", "active A", "join", "rename A Puff", "shade flat", "export puff.glb"])

# ---------------------------------------------------------------- splash
# A crown of water: eight spikes round a ring 0.35 m wide and a central column; pale on the snow ramp.
sp = ["# Splash crown. Generated by make_env.py.", "new", mat("Spray", "pale")]
for i in range(8):
    a = i * math.pi / 4
    h = 0.55 if i % 2 == 0 else 0.38
    x, y = 0.3 * math.cos(a), 0.3 * math.sin(a)
    sp += [f"add mesh cone --name S{i} --vertices 4 --radius1 0.08 --radius2 0 --depth {h} --location 0 0 {h / 2}",
           f"translate {x:.3f} {y:.3f} 0", "material assign Spray"]
sp += ["add mesh cone --name Col --vertices 5 --radius1 0.12 --radius2 0.03 --depth 0.75 --location 0 0 0.375",
       "material assign Spray",
       "add mesh cylinder --name Ring --vertices 10 --radius 0.42 --depth 0.06 --location 0 0 0.03", "material assign Spray",
       "select all", "active Col", "join", "rename Col Splash", "shade flat", "export splash.glb"]
write("splash", sp)

# ---------------------------------------------------------------- floating chunk
write("chunk", [
    "# A small ice chunk floating in the sea, 0.9 x 0.6 m, 0.14 m above the water. Generated by make_env.py.",
    "new", mat("Snow", "pale"), mat("Ice", "mint"),
    "add mesh cylinder --name Chunk --vertices 6 --radius 0.5 --depth 0.3 --location 0 0 0",
    "scale 0.9 0.6 1", "apply --scale", "material assign Ice",
    "active Chunk", "mode edit", 'select face where "normal.z > 0.9"', "material assign Snow",
    'select vert where "pos.z > 0.1"', "randomize --amount 0.04 --seed 11",
    'select face where "normal.z < -0.9"', "delete only-faces", "mode object",
    "shade flat", "export chunk.glb"])

# ---------------------------------------------------------------- iceberg (backdrop)
write("berg", [
    "# A distant iceberg, 2.4 m wide, 1.3 m tall: a faceted peak and a lower shoulder. Generated by make_env.py.",
    "new", mat("Snow", "pale"), mat("Ice", "mint"),
    "add mesh cone --name Peak --vertices 5 --radius1 0.9 --radius2 0.12 --depth 1.4 --location -0.3 0 0.6", "material assign Ice",
    "add mesh cone --name Shoulder --vertices 5 --radius1 0.8 --radius2 0.25 --depth 0.8 --location 0.55 0.1 0.3", "material assign Ice",
    "select Peak Shoulder", "active Peak", "join", "rename Peak Berg",
    "active Berg", "mode edit",
    'select vert where "pos.z > 0.05"', "randomize --amount 0.08 --seed 21",
    'select face where "normal.z > 0.55"', "material assign Snow",
    'select face where "normal.z < -0.9"', "delete only-faces",
    "mode object", "shade flat", "export berg.glb"])

# ---------------------------------------------------------------- mountain ridge (far backdrop)
rnd = random.Random(31)
rg = ["# A far range of snowy peaks, 16 m wide, 0.6-1.1 m tall (tiles side by side). Generated by make_env.py.",
      "new", mat("Rock", "mint"), mat("Snow", "pale")]
names = []
x = -8.0
i = 0
while x < 8.0:
    w = rnd.uniform(1.4, 2.4)
    h = rnd.uniform(0.6, 1.1)
    cx = x + w / 2
    rg += [f"add mesh cone --name M{i} --vertices 4 --radius1 {w / 2:.2f} --radius2 0 --depth {h:.2f} --location {cx:.2f} 0 {h / 2:.2f} --rotation 0 0 45",
           "apply --rotation", f"scale 1 0.5 1", "apply --scale", "apply --location", "material assign Rock",
           f"add mesh cone --name C{i} --vertices 4 --radius1 {0.42 * w / 2:.2f} --radius2 0 --depth {0.42 * h:.2f} --location {cx:.2f} -0.01 {0.79 * h:.2f} --rotation 0 0 45",
           "apply --rotation", f"scale 1 0.5 1", "apply --scale", "apply --location", "material assign Snow"]
    names += [f"M{i}", f"C{i}"]
    x += w * 0.7
    i += 1
rg += [f"select {' '.join(names)}", "active M0", "join", "rename M0 Ridge", "active Ridge", "mode edit",
       'select face where "normal.z < -0.9"', "delete only-faces", "mode object",
       "shade flat", "export ridge.glb"]
write("ridge", rg)

# ---------------------------------------------------------------- the sea
write("water", [
    "# The sea: a plane 9 m wide from 7 m in front of the run to 8 m behind it, 0.3 m under the ice top.",
    "# It travels with the camera (the game snaps it to the art grid). Generated by make_env.py.",
    "new", mat("Water", "teal"),
    "add mesh plane --name Sea --size 1 --location 0 0.5 -0.3",
    "scale 9 15 1", "apply --scale", "material assign Water",
    "shade flat", "export water.glb"])

# ---------------------------------------------------------------- wave crests
# An 8 m strip of small mint wave crests standing on the sea in front of and behind the run (low
# wedges facing the camera: flat marks on the water would vanish at the 12 degree pitch). Two copies
# tile the sea; they stay put in the world, so the sea reads as moving past.
rnd = random.Random(41)
wv = ["# Wave crests over an 8 m strip of sea. Generated by make_env.py.", "new", mat("Wave", "mint")]
names = []
for i in range(34):
    x = rnd.uniform(-4, 4)
    z = rnd.uniform(1.3, 6.0) if i % 3 else -rnd.uniform(1.4, 4.5)
    L = rnd.uniform(0.3, 0.5)
    wv += [f"add mesh cube --name W{i} --size 1 --location {x:.2f} {-z:.2f} -0.26",
           f"scale {L:.2f} 0.07 0.08", "apply --scale", "active W" + str(i), "mode edit",
           'select face where "normal.z > 0.9"', "scale 0.6 0.2 1", "mode object", "apply --location"]
    names.append(f"W{i}")
wv += [f"select {' '.join(names)}", "material assign Wave", "active W0", "join", "rename W0 Waves",
       "active Waves", "mode edit", 'select face where "normal.z < -0.9 || normal.y > 0.5"', "delete only-faces",
       "mode object", "shade flat", "export waves.glb"]
write("waves", wv)
